        while(i >= 0 && j >= 0){
            nums1[k--] = (nums1[i] < nums2[j]) ? nums2[j--]:nums1[i--];
        }
        if(j >= 0){
            while(j>=0){
                nums1[k--] = nums2[j--];
            }
        }
        return;
    }
};

